// ResilienceServer is the server API for Resilience service.
// All implementations should embed UnimplementedResilienceServer
// for forward compatibility.
//
// Resilience exposes the high-availability state of the proxies (circuit breaker status and effective
// settings) and manages automatic failover policies and the history of performed failovers.
type ResilienceServer interface {
	ListRuntimeStorages(context.Context, *emptypb.Empty) (*RuntimeStorageList, error)
	CreateRuntimeStorage(context.Context, *CreateRuntimeStorageRequest) (*RuntimeStorage, error)
	UpdateRuntimeStorage(context.Context, *UpdateRuntimeStorageRequest) (*RuntimeStorage, error)
	DeleteRuntimeStorage(context.Context, *RuntimeStorageName) (*emptypb.Empty, error)
	TestRuntimeStorage(context.Context, *TestRuntimeStorageRequest) (*TestS3UserCredentialsResponse, error)
	// GetRuntimeStorage returns one storage with its connection account (never the secret) and the last connection test.
	GetRuntimeStorage(context.Context, *RuntimeStorageName) (*RuntimeStorage, error)
	// TestStorageConnection runs the connection checks of the scale plan (2.4) against unsaved settings (storage +
	// connection_account) or an existing storage (name). It never fails because a check failed: the failing steps are in
	// the result. Results of existing storages are stored with the storage (last_test).
	TestStorageConnection(context.Context, *TestStorageConnectionRequest) (*StorageTestResult, error)
	// RotateStorageConnectionAccount replaces the connection account of a storage: the new account is tested first,
	// then switched atomically. The previous account is kept (sealed) so that proxies that have not polled yet keep working.
	RotateStorageConnectionAccount(context.Context, *RotateStorageConnectionAccountRequest) (*RuntimeStorage, error)
	// GetProxyStatus returns all live proxy instances with the health of their storages and effective settings.
	// Proxies publish their status periodically; an instance that stopped publishing disappears after a short TTL.
	GetProxyStatus(context.Context, *emptypb.Empty) (*ProxyStatusList, error)
	// GetStatsHistory returns the traffic rates of all proxies over the last `range` (5m, 15m, 1h or 6h), summed
	// across proxies per time bucket (10s; 30s for 1h; 2m for 6h), plus the latest rates of every proxy.
	// Proxies record a sample every 10s into Redis (kept 6h), so history survives UI reloads.
	GetStatsHistory(context.Context, *StatsHistoryRequest) (*StatsHistory, error)
	// ListFailoverPolicies returns all failover policies sorted by source storage.
	ListFailoverPolicies(context.Context, *emptypb.Empty) (*FailoverPolicyList, error)
	// SetFailoverPolicy creates or replaces the failover policy of a source storage.
	// Source and targets must be configured storages.
	SetFailoverPolicy(context.Context, *FailoverPolicy) (*emptypb.Empty, error)
	// DeleteFailoverPolicy removes the failover policy of a source storage.
	DeleteFailoverPolicy(context.Context, *FailoverPolicySource) (*emptypb.Empty, error)
	// ListFailoverEvents returns the performed failovers that were not yet cleared.
	ListFailoverEvents(context.Context, *emptypb.Empty) (*FailoverEventList, error)
	// DeleteFailoverEvent clears the record of a performed failover, e.g. after manual failback.
	DeleteFailoverEvent(context.Context, *FailoverEventID) (*emptypb.Empty, error)
	// ListAccessPolicies returns all proxy account access policies sorted by user.
	ListAccessPolicies(context.Context, *emptypb.Empty) (*AccessPolicyList, error)
	// SetAccessPolicy creates or replaces the access policy of a proxy user.
	// Proxies pick up changes within a few seconds (policy cache TTL).
	SetAccessPolicy(context.Context, *AccessPolicy) (*emptypb.Empty, error)
	// DeleteAccessPolicy removes the access policy of a proxy user: the user gets full access again.
	DeleteAccessPolicy(context.Context, *AccessPolicyUser) (*emptypb.Empty, error)
	// ListProxyAccounts returns the accounts able to authenticate against live proxies (users of storage credentials
	// used by the proxy and custom credentials) with their effective access policy. Secrets are never returned.
	// Runtime-managed ("dynamic") accounts are listed with source "dynamic" and their lifecycle metadata.
	ListProxyAccounts(context.Context, *emptypb.Empty) (*ProxyAccountList, error)
	// CreateProxyAccount creates a runtime-managed proxy account for an existing storage user and returns the
	// generated access key id and secret. The secret is returned ONLY in this response.
	// Fails with FailedPrecondition if the dynamic credentials master password is not configured.
	CreateProxyAccount(context.Context, *CreateProxyAccountRequest) (*ProxyAccountSecret, error)
	// RotateProxyAccountSecret generates a new secret. The previous secret keeps working for grace_period.
	// The new secret is returned ONLY in this response.
	RotateProxyAccountSecret(context.Context, *RotateProxyAccountSecretRequest) (*ProxyAccountSecret, error)
	// SetProxyAccountStatus enables ("active") or disables ("disabled") a dynamic account.
	SetProxyAccountStatus(context.Context, *SetProxyAccountStatusRequest) (*emptypb.Empty, error)
	// DeleteProxyAccount permanently removes a dynamic account.
	DeleteProxyAccount(context.Context, *ProxyAccountKey) (*emptypb.Empty, error)
	// ListS3Users returns the union of all users across storages with the credential state per storage (never the
	// secret), the proxy access key counts and the access policy summary.
	ListS3Users(context.Context, *emptypb.Empty) (*S3UserList, error)
	// CreateS3User creates a user with dynamic credentials on the given storages (the main storage is required),
	// optionally verifying them first, setting an access policy and creating the first proxy access key.
	// Fails with FailedPrecondition if dynamic credentials are not enabled. Partial changes are rolled back.
	CreateS3User(context.Context, *CreateS3UserRequest) (*CreateS3UserResponse, error)
	// UpdateS3UserCredentials sets or replaces the dynamic credentials of an existing user on one storage.
	// Credentials defined in the worker config cannot be changed (FailedPrecondition).
	UpdateS3UserCredentials(context.Context, *UpdateS3UserCredentialsRequest) (*emptypb.Empty, error)
	// DeleteS3User removes the dynamic credentials, dynamic proxy access keys and the access policy of a user.
	// Refused with FailedPrecondition (listing all reasons) if any credentials come from config or if replications,
	// routings or failover events reference the user. Active access keys also block deletion unless force is set.
	DeleteS3User(context.Context, *DeleteS3UserRequest) (*DeleteS3UserResponse, error)
	// TestS3UserCredentials checks credentials against one storage with a ListBuckets call.
	// Uses the given credentials or, if not given, the stored credentials of the user.
	TestS3UserCredentials(context.Context, *TestS3UserCredentialsRequest) (*TestS3UserCredentialsResponse, error)
	// ListConsoleUsers returns the users able to sign in to the management API: config users (read-only) and
	// managed users stored in Redis. Never returns password hashes. Admin only.
	ListConsoleUsers(context.Context, *emptypb.Empty) (*ConsoleUserList, error)
	// CreateConsoleUser creates a managed console user with a given or a generated (returned once) password.
	CreateConsoleUser(context.Context, *CreateConsoleUserRequest) (*CreateConsoleUserResponse, error)
	// UpdateConsoleUser changes the role and/or the disabled flag of a managed user. Sessions are affected immediately.
	UpdateConsoleUser(context.Context, *UpdateConsoleUserRequest) (*emptypb.Empty, error)
	// ResetConsoleUserPassword sets or generates a new password of a managed user, forces a password change at the
	// next login and revokes all sessions of the user.
	ResetConsoleUserPassword(context.Context, *ResetConsoleUserPasswordRequest) (*ResetConsoleUserPasswordResponse, error)
	// DeleteConsoleUser removes a managed user. Its sessions stop working immediately.
	DeleteConsoleUser(context.Context, *ConsoleUserName) (*emptypb.Empty, error)
}

